if (opcode == WS_OPCODE_CLOSE) {
    unsigned int close_code = (flen >= 2)
        ? (((unsigned int)buf[0] << 8) | buf[1]) : 0;
    syslog(LOG_WARNING,
        "[%s] Server sent WS close (len=%zu, code=%u, reason=%.*s)\n",
        TAG, flen, close_code,
        (int)(flen > 2 ? flen - 2 : 0),
        (flen > 2 ? (const char*)buf + 2 : ""));
    free(buf);
    /* 2026-08-15 P78 修复（上板诊断实锤）：服务器正常完成会话时
     * 发 WS close code=1000 reason="finish last sequence"（收到客户端
     * 结束帧后的正常关闭），原实现一律 -ECONNRESET → -104 误报。
     * code=1000 / 无 code 视为正常结束（等同最终帧，调用方按
     * text_out 判成功或 no-text），其余错误码（如 1013 音频静音）
     * 仍按连接错误返回。 */
    if (close_code == 1000 || close_code == 0) {
        return 1;
    }
    return -ECONNRESET;
}

