        int sample_count = (int)got / 2;

        /* 2026-08-15 P78 修复（上板诊断实锤）：原硬 clamp ±32767 在
         * ×32 增益 + 大声说话时削波（chunk#9/10 peak=32768 满幅，波形
         * 削平 → ASR 识别不出 text）。改折线软限幅：超过 SOFT_CLIP
         * 部分衰减，保留 ×32 增益（batch P75 能量阈值 <2000 不受影响，
         * stream 大声不再削平波形）。 */
        const int32_t SOFT_CLIP = 20000;

        for (int i = 0; i < sample_count; i++) {
            int32_t v = (int32_t)samples[i] * AGENT_AUDIO_CAPTURE_GAIN;

            if (v > SOFT_CLIP) {
                v = SOFT_CLIP + (v - SOFT_CLIP) / 2;
                if (v > 32767) {
                    v = 32767;
                }
            } else if (v < -SOFT_CLIP) {
                v = -SOFT_CLIP - ((-v) - SOFT_CLIP) / 2;
                if (v < -32768) {
                    v = -32768;
                }
            }

            samples[i] = (int16_t)v;
        }
    }
#endif

