229	static int read_pcm_file(const char* path,
230	    unsigned char** out, size_t* out_len)
231	{
232	    int fd = open(path, O_RDONLY);
233	
234	    if (fd < 0) {
235	        syslog(LOG_ERR, "[%s] Cannot open %s: %d\n",
236	            TAG, path, errno);
237	        return -errno;
238	    }
239	
240	    off_t fsize = lseek(fd, 0, SEEK_END);
241	
242	    if (fsize <= 0 || (size_t)fsize > AGENT_VOICE_PCM_BUF_SIZE) {
243	        syslog(LOG_ERR, "[%s] File too large or empty: %ld\n",
244	            TAG, (long)fsize);
245	        close(fd);
246	        return -EFBIG;
247	    }
248	
249	    lseek(fd, 0, SEEK_SET);
250	
251	    unsigned char* buf = malloc((size_t)fsize);
252	
253	    if (!buf) {
254	        close(fd);
255	        return -ENOMEM;
256	    }
257	
258	    ssize_t nread = read(fd, buf, (size_t)fsize);
259	
260	    close(fd);
261	
262	    if (nread != (ssize_t)fsize) {
263	        free(buf);
264	        return -EIO;
265	    }
