267	    /* 2026-08-12 TASK-02：WAV 头剥离——arecord 落盘是 WAV（RIFF/WAVE +
268	     * 44B 头），原实现整文件当 PCM 发给 ASR，头垃圾会污染首包。检测
269	     * WAV 魔数后解析 chunk 链，只保留 data 段（PCM 数据）。 */
270	    if ((size_t)fsize >= 12
271	        && memcmp(buf, "RIFF", 4) == 0
272	        && memcmp(buf + 8, "WAVE", 4) == 0) {
273	        size_t off = 12;
274	
275	        while (off + 8 <= (size_t)fsize) {
276	            uint32_t clen = (uint32_t)buf[off + 4]
277	                | ((uint32_t)buf[off + 5] << 8)
278	                | ((uint32_t)buf[off + 6] << 16)
279	                | ((uint32_t)buf[off + 7] << 24);
280	
281	            if (memcmp(buf + off, "data", 4) == 0) {
282	                size_t data_len = clen;
283	
284	                if (off + 8 + data_len > (size_t)fsize) {
285	                    data_len = (size_t)fsize - off - 8;
286	                }
287	                memmove(buf, buf + off + 8, data_len);
288	                *out = buf;
289	                *out_len = data_len;
290	                return 0;
291	            }
292	            off += 8 + clen + (clen & 1);   /* chunk 2 字节对齐 */
293	        }
294	    }
295	
296	    *out = buf;
297	    *out_len = (size_t)fsize;
298	    return 0;
299	}
